# 🟢 低风险：只读/信息收集，通常无副作用
# ========== 1. 集群CPU使用概况 ==========
# 查看节点CPU使用情况
kubectl top nodes

# 分析CPU使用率最高的节点
kubectl top nodes --sort-by=cpu | tail -5

# 查看Pod CPU使用情况
kubectl top pods --all-namespaces --sort-by=cpu | head -10

# ========== 2. CPU资源分配检查 ==========
# 检查CPU请求和限制配置
kubectl get pods --all-namespaces -o jsonpath='{
    range .items[*]
}{
        .metadata.namespace
}{
        "/"
}{
        .metadata.name
}{
        "\t"
}{
        .spec.containers[*].resources.requests.cpu
}{
        "\t"
}{
        .spec.containers[*].resources.limits.cpu
}{
        "\n"
}{
    end
}' | sort -k3 -n | tail -10

# 分析CPU资源碎片化
kubectl describe nodes | grep -E "(CPU Requests|CPU Limits)" -A3

# 检查CPU压力事件
kubectl get events --field-selector reason=SystemOOM,type=Warning --sort-by='.lastTimestamp'

# ========== 3. 进程级别CPU分析 ==========
# 在节点上分析CPU使用
for node in $(kubectl get nodes -o jsonpath='{.items[*].metadata.name}'); do
    echo "=== Node: $node ==="
    kubectl debug node/$node --image=busybox -it -- sh -c "
        echo 'Top CPU consuming processes:'
        ps aux --sort=-%cpu | head -10
        echo 'CPU info:'
        cat /proc/cpuinfo | grep processor | wc -l
        echo 'Load average:'
        uptime
    "
done

