kind: Pod
metadata:
  name: iperf-client
  namespace: default
spec:
  containers:
  - name: iperf
    image: networkstatic/iperf3
    command: ["sleep", "3600"]
EOF

# 执行带宽测试
kubectl exec iperf-client -- iperf3 -c iperf-server.default.pod.cluster.local -t 30 -P 4

